#include "GuestRasterState.h"
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
void oracle(uint8_t[24],const SatchelGuestNVNStateRequest *);
void oracle_decode(unsigned,const uint8_t[24],SatchelGuestNVNStateDecoded *);
void satchel_cpu_probe_test_write_allocation_failure(int);
static unsigned checks;
static void check(int v,const char *s){++checks;if(!v){fprintf(stderr,"FAIL: %s\n",s);exit(1);}}
static const uint64_t DATA=0x20000,OBJECT=0x20100,ALIAS=0x40000;
static unsigned guard_calls;static int recursive;
static int allow(void *p,SatchelCPUProbe *cpu,uint64_t address,uint64_t size){(void)p;(void)cpu;(void)address;(void)size;++guard_calls;return 1;}
static int deny(void *p,SatchelCPUProbe *cpu,uint64_t address,uint64_t size){(void)p;(void)cpu;(void)address;(void)size;return 0;}
static int protect(void *p,SatchelCPUProbe *cpu,uint64_t address,uint64_t size){int overlap=0;return satchel_cpu_probe_physical_overlap(cpu,address,size,*(uint64_t*)p,4096,&overlap)&&!overlap;}
static int recurse(void *p,SatchelCPUProbe *cpu,uint64_t address,uint64_t size){(void)p;(void)size;SatchelGuestNVNStateRequest r={.operation=SATCHEL_GNS_COLOR_DEFAULTS,.x={address}};recursive=satchel_guest_nvn_state_apply(cpu,&r,allow,NULL).status;return 1;}
static SatchelCPUProbe *make(void){uint32_t code[]={0xd503201f,0x14000000};uint8_t data[8192];memset(data,0xa5,sizeof data);const SatchelCPUProbeRegion regions[]={{0x10000,code,sizeof code,sizeof code,SATCHEL_CPU_READ|SATCHEL_CPU_EXECUTE},{DATA,data,sizeof data,sizeof data,SATCHEL_CPU_READ|SATCHEL_CPU_WRITE}};char error[256];SatchelCPUProbe *p=satchel_cpu_probe_create(regions,2,0x10000,error,sizeof error);check(p!=NULL,"create original CPU memory");return p;}
static SatchelGuestNVNStateResult run(SatchelCPUProbe*p,unsigned op,uint64_t a,uint64_t b,uint64_t c,uint64_t d,uint64_t e){SatchelGuestNVNStateRequest r={.operation=op,.x={OBJECT,a,b,c,d,e}};return satchel_guest_nvn_state_apply(p,&r,allow,NULL);}
static unsigned family(unsigned op){return op<=SATCHEL_GNS_COLOR_ALPHA?1:op<=SATCHEL_GNS_CHANNEL_MASK?2:op<=SATCHEL_GNS_POLYGON_OFFSET?3:op<=SATCHEL_GNS_STENCIL_OP?4:op<=SATCHEL_GNS_MULTISAMPLE_GRID_ENABLE?5:op<=SATCHEL_GNS_ATTRIBUTE_STREAM?6:7;}
static unsigned defaults[]={0,SATCHEL_GNS_COLOR_DEFAULTS,SATCHEL_GNS_CHANNEL_DEFAULTS,SATCHEL_GNS_POLYGON_DEFAULTS,SATCHEL_GNS_DEPTH_DEFAULTS,SATCHEL_GNS_MULTISAMPLE_DEFAULTS,SATCHEL_GNS_ATTRIBUTE_DEFAULTS,SATCHEL_GNS_STREAM_DEFAULTS};
static void arguments(SatchelGuestNVNStateRequest *r,unsigned seed){uint64_t *x=r->x;unsigned a=seed;for(unsigned i=1;i<6;i++)x[i]=(a+i)&1;
 switch(r->operation){case SATCHEL_GNS_COLOR_BLEND:case SATCHEL_GNS_CHANNEL_MASK:x[1]=a%8;break;case SATCHEL_GNS_COLOR_LOGIC:x[1]=a%16;break;case SATCHEL_GNS_COLOR_ALPHA:case SATCHEL_GNS_DEPTH_FUNC:x[1]=1+a%8;break;
 case SATCHEL_GNS_POLYGON_CULL:x[1]=a%4;break;case SATCHEL_GNS_POLYGON_FRONT:x[1]=a%2;break;case SATCHEL_GNS_POLYGON_MODE:x[1]=a%3;break;case SATCHEL_GNS_POLYGON_OFFSET:x[1]=a%8;break;
 case SATCHEL_GNS_STENCIL_FUNC:x[1]=a%4;x[2]=1+a%8;break;case SATCHEL_GNS_STENCIL_OP:x[1]=a%4;x[2]=1+a%8;x[3]=1+(a+1)%8;x[4]=1+(a+2)%8;break;
 case SATCHEL_GNS_MULTISAMPLE_SAMPLES:case SATCHEL_GNS_MULTISAMPLE_RASTER_SAMPLES:{unsigned n[]={0,1,2,4,8,16};x[1]=n[a%6];break;}case SATCHEL_GNS_MULTISAMPLE_COVERAGE_MODE:x[1]=a%4;break;case SATCHEL_GNS_MULTISAMPLE_COVERAGE_OUTPUT:x[1]=a%8;break;
 case SATCHEL_GNS_ATTRIBUTE_FORMAT:x[1]=a%157;x[2]=(a*257)%0x80000;break;case SATCHEL_GNS_ATTRIBUTE_STREAM:x[1]=a%32;break;case SATCHEL_GNS_STREAM_STRIDE:x[1]=a*UINT64_C(0x10101);break;case SATCHEL_GNS_STREAM_DIVISOR:x[1]=a;break;default:break;}}
static void failure(SatchelCPUProbe*p,SatchelGuestNVNStateRequest r,unsigned status,SatchelGuestNVNStateGuard guard,void*ctx){uint8_t before[8192],after[8192];check(satchel_cpu_probe_read(p,DATA,before,sizeof before),"snapshot failure canary");check(satchel_guest_nvn_state_apply(p,&r,guard,ctx).status==status,"expected failure status");check(satchel_cpu_probe_read(p,DATA,after,sizeof after)&&!memcmp(before,after,sizeof before),"failure preserves entire memory");}
static int cancel(void *ctx){SatchelCPUProbe*p=ctx;SatchelGuestNVNStateRequest r={.operation=SATCHEL_GNS_COLOR_DEFAULTS,.x={OBJECT}};check(satchel_guest_nvn_state_apply(p,&r,allow,NULL).status==SATCHEL_GNS_MEMORY,"active CPU refuses checked access");return 1;}
int main(void){SatchelCPUProbe*p=make();uint8_t expected[24],observed[24],before[8192],after[8192];
 for(unsigned op=1;op<=SATCHEL_GNS_STREAM_DIVISOR;op++)for(unsigned seed=0;seed<48;seed++){unsigned k=family(op),n=satchel_guest_nvn_state_size(k);SatchelGuestNVNStateRequest init={.operation=defaults[k],.x={OBJECT}},r={.operation=op,.x={OBJECT}};arguments(&r,seed);memset(expected,0,24);oracle(expected,&init);check(satchel_guest_nvn_state_apply(p,&init,allow,NULL).status==SATCHEL_GNS_OK,"initialize state");check(satchel_cpu_probe_read(p,DATA,before,sizeof before),"full before canary");oracle(expected,&r);check(satchel_guest_nvn_state_apply(p,&r,allow,NULL).status==SATCHEL_GNS_OK,"actual setter");check(satchel_cpu_probe_read(p,OBJECT,observed,n)&&!memcmp(expected,observed,n),"independent pinned bitfield/default oracle");check(satchel_cpu_probe_read(p,DATA,after,sizeof after),"read whole canary");memcpy(before+(OBJECT-DATA),expected,n);check(!memcmp(before,after,sizeof before),"exact full object span only");SatchelGuestNVNStateDecoded d;memset(&d,0xa5,sizeof d);check(satchel_guest_nvn_state_decode(k,observed,n,&d)==SATCHEL_GNS_OK && d.kind==k,"actual bounded decode");SatchelGuestNVNStateDecoded reference;oracle_decode(k,observed,&reference);check(!memcmp(&d,&reference,sizeof d),"independent decoded fields and zero unused fields");for(unsigned size=0;size<n;size++){SatchelGuestNVNStateDecoded keep=d;check(satchel_guest_nvn_state_decode(k,observed,size,&d)==SATCHEL_GNS_INVALID&&!memcmp(&keep,&d,sizeof d),"truncated decode unchanged");}}
 // Values at the exact retained representation boundaries, without truncation.
 const struct{unsigned op;uint64_t a,b;}edges[]={{SATCHEL_GNS_ATTRIBUTE_FORMAT,156,0x7ffff},{SATCHEL_GNS_ATTRIBUTE_STREAM,31,0},{SATCHEL_GNS_STREAM_STRIDE,UINT32_MAX,0},{SATCHEL_GNS_STREAM_DIVISOR,INT32_MAX,0}};
 for(unsigned i=0;i<sizeof edges/sizeof edges[0];i++){unsigned k=family(edges[i].op),n=satchel_guest_nvn_state_size(k);SatchelGuestNVNStateRequest init={.operation=defaults[k],.x={OBJECT}},r={.operation=edges[i].op,.x={OBJECT,edges[i].a,edges[i].b}};memset(expected,0,24);oracle(expected,&init);oracle(expected,&r);check(satchel_guest_nvn_state_apply(p,&init,allow,NULL).status==0 && satchel_guest_nvn_state_apply(p,&r,allow,NULL).status==0 && satchel_cpu_probe_read(p,OBJECT,observed,n) && !memcmp(expected,observed,n),"full-width representation endpoint");}
 // Whole24-byte defaults must erase reserved bytes, not leave caller garbage.
 memset(expected,0xff,24);check(satchel_cpu_probe_write(p,OBJECT,expected,24),"dirty multisample seed");check(run(p,SATCHEL_GNS_MULTISAMPLE_DEFAULTS,0,0,0,0,0).status==SATCHEL_GNS_OK && satchel_cpu_probe_read(p,OBJECT,observed,24),"whole multisample default");for(unsigned i=0;i<24;i++)check(observed[i]==(i==0),"reserved default byte zero");
 // Narrow integer ABI: booleans consume low byte, enum/int upper bits ignored.
 check(run(p,SATCHEL_GNS_COLOR_DEFAULTS,0,0,0,0,0).status==SATCHEL_GNS_OK,"boolean defaults");check(run(p,SATCHEL_GNS_COLOR_BLEND,UINT64_C(0xabcdef0000000000),0x100,0,0,0).status==SATCHEL_GNS_OK,"low-byte false high-register noise");check(run(p,SATCHEL_GNS_COLOR_BLEND,0,0x1ff,0,0,0).status==SATCHEL_GNS_OK,"low-byte true");check(satchel_cpu_probe_read(p,OBJECT,observed,4)&&observed[0]==1,"actual boolean field");
 const struct{unsigned op;uint64_t a,b,c,d;}bad[]={{SATCHEL_GNS_COLOR_BLEND,8,0,0,0},{SATCHEL_GNS_COLOR_LOGIC,16,0,0,0},{SATCHEL_GNS_COLOR_ALPHA,0,0,0,0},{SATCHEL_GNS_COLOR_ALPHA,9,0,0,0},{SATCHEL_GNS_CHANNEL_MASK,8,0,0,0},{SATCHEL_GNS_POLYGON_CULL,4,0,0,0},{SATCHEL_GNS_POLYGON_FRONT,2,0,0,0},{SATCHEL_GNS_POLYGON_MODE,3,0,0,0},{SATCHEL_GNS_POLYGON_OFFSET,8,0,0,0},{SATCHEL_GNS_DEPTH_FUNC,9,0,0,0},{SATCHEL_GNS_STENCIL_FUNC,4,1,0,0},{SATCHEL_GNS_STENCIL_FUNC,3,0,0,0},{SATCHEL_GNS_STENCIL_OP,3,1,1,9},{SATCHEL_GNS_MULTISAMPLE_SAMPLES,3,0,0,0},{SATCHEL_GNS_MULTISAMPLE_SAMPLES,UINT64_MAX,0,0,0},{SATCHEL_GNS_MULTISAMPLE_COVERAGE_MODE,4,0,0,0},{SATCHEL_GNS_MULTISAMPLE_COVERAGE_OUTPUT,8,0,0,0},{SATCHEL_GNS_ATTRIBUTE_FORMAT,157,0,0,0},{SATCHEL_GNS_ATTRIBUTE_FORMAT,46,0x80000,0,0},{SATCHEL_GNS_ATTRIBUTE_FORMAT,46,UINT64_MAX,0,0},{SATCHEL_GNS_ATTRIBUTE_STREAM,32,0,0,0},{SATCHEL_GNS_STREAM_STRIDE,UINT64_C(0x100000000),0,0,0},{SATCHEL_GNS_STREAM_DIVISOR,UINT64_C(0x80000000),0,0,0}};
 for(unsigned i=0;i<sizeof bad/sizeof bad[0];i++){check(run(p,defaults[family(bad[i].op)],0,0,0,0,0).status==0,"negative initialized state");SatchelGuestNVNStateRequest r={.operation=bad[i].op,.x={OBJECT,bad[i].a,bad[i].b,bad[i].c,bad[i].d}};failure(p,r,SATCHEL_GNS_UNSUPPORTED,allow,NULL);}
 for(unsigned k=1;k<=7;k++){unsigned n=satchel_guest_nvn_state_size(k);SatchelGuestNVNStateRequest r={.operation=defaults[k],.x={OBJECT}};failure(p,r,SATCHEL_GNS_MEMORY,deny,NULL);failure(p,r,SATCHEL_GNS_INVALID,NULL,NULL);r.x[0]=DATA+8192-n+1;failure(p,r,SATCHEL_GNS_MEMORY,allow,NULL);r.x[0]=UINT64_MAX;failure(p,r,SATCHEL_GNS_MEMORY,allow,NULL);r.x[0]=0x10000;failure(p,r,SATCHEL_GNS_MEMORY,allow,NULL);r.x[0]=OBJECT;satchel_cpu_probe_test_write_allocation_failure(1);failure(p,r,SATCHEL_GNS_ALLOCATION,allow,NULL);check(satchel_guest_nvn_state_apply(p,&r,recurse,NULL).status==0&&recursive==SATCHEL_GNS_BUSY,"guard cannot reenter mutator");}
 // Independent reserved-field decoder negatives preserve output.
 const struct{unsigned k,index,bit;}reserved[]={{1,2,1},{3,1,1},{4,4,128},{5,10,1},{5,23,128}};
 for(unsigned i=0;i<sizeof reserved/sizeof reserved[0];i++){unsigned k=reserved[i].k,n=satchel_guest_nvn_state_size(k);check(run(p,defaults[k],0,0,0,0,0).status==0&&satchel_cpu_probe_read(p,OBJECT,observed,n),"reserved fixture");observed[reserved[i].index]|=reserved[i].bit;SatchelGuestNVNStateDecoded d,keep;memset(&d,0xa5,sizeof d);keep=d;check(satchel_guest_nvn_state_decode(k,observed,n,&d)==SATCHEL_GNS_UNSUPPORTED&&!memcmp(&d,&keep,sizeof d),"reserved bits fail closed");}
 // Real retained physical alias: virtual disjointness must not bypass protection.
 check(satchel_cpu_probe_map_alias(p,ALIAS,DATA,4096)==SATCHEL_CPU_MAP_OK,"create protected physical alias");uint64_t protected=DATA;SatchelGuestNVNStateRequest ar={.operation=SATCHEL_GNS_COLOR_DEFAULTS,.x={ALIAS+256}};check(satchel_guest_nvn_state_apply(p,&ar,protect,&protected).status==SATCHEL_GNS_MEMORY,"physical alias guard rejects destination");check(satchel_cpu_probe_read(p,ALIAS+256,observed,4),"alias unchanged readable");check(satchel_cpu_probe_unmap_alias(p,ALIAS,DATA,4096)==SATCHEL_CPU_MAP_OK,"restore alias");
 char error[256];SatchelCPUProbe*s=satchel_cpu_probe_create_shared(p,0x10000,error,sizeof error);check(s!=NULL,"shared context");check(satchel_cpu_probe_set_x(s,0,0x1234),"set caller register");check(run(s,SATCHEL_GNS_COLOR_DEFAULTS,0,0,0,0,0).status==0&&satchel_cpu_probe_read(p,OBJECT,observed,4),"sibling shares real state bytes");uint64_t x;check(satchel_cpu_probe_get_x(s,0,&x)&&x==0x1234,"setter never overwrites caller X0");satchel_cpu_probe_destroy(s);
 check(satchel_cpu_probe_run(p,1,cancel,p).reason==SATCHEL_CPU_CANCELLED,"active CPU callback denied without mutation");satchel_cpu_probe_destroy(p);printf("%u checked NVN state assertions passed (original fixtures; no rendering claim).\n",checks);return 0;}
